-- The showcase palette: a short, intentional set of nodes that read as
-- architecture and exhibition design rather than a museum of drawtypes.
--
-- Everything here is deliberately GLES2/WebGL friendly: 16x16 tiles, no
-- connected textures, no mesh nodes, no shader tricks. Animated tiles are
-- vertical filmstrips, which the browser renderer handles the same way it
-- handles water in any other game.
--
-- Textures are generated by util/content/generate_luanti_web_textures.py.

lw_nodes = {}

-- 16 dyed cubes. One greyscale weave tinted with [multiply, so the whole
-- palette costs a single 16x16 texture instead of sixteen.
lw_nodes.wool_colors = {
	{name = "white", desc = "White", hex = "#e9e9e4"},
	{name = "grey", desc = "Grey", hex = "#9a9a95"},
	{name = "dark_grey", desc = "Dark Grey", hex = "#4c4c48"},
	{name = "black", desc = "Black", hex = "#1c1c1a"},
	{name = "red", desc = "Red", hex = "#bf2f31"},
	{name = "orange", desc = "Orange", hex = "#e07a22"},
	{name = "yellow", desc = "Yellow", hex = "#e6c22f"},
	{name = "green", desc = "Green", hex = "#5aa83c"},
	{name = "dark_green", desc = "Dark Green", hex = "#2d6b2d"},
	{name = "cyan", desc = "Cyan", hex = "#31b0ae"},
	{name = "blue", desc = "Blue", hex = "#2f5cba"},
	{name = "violet", desc = "Violet", hex = "#6c3fb8"},
	{name = "magenta", desc = "Magenta", hex = "#b43196"},
	{name = "pink", desc = "Pink", hex = "#e38cae"},
	{name = "brown", desc = "Brown", hex = "#7b5230"},
	{name = "tan", desc = "Tan", hex = "#c8a97a"},
}

function lw_nodes.wool_texture(hex)
	return "lw_wool.png^[multiply:" .. hex
end

-- Every palette node carries lw_palette so the material library can list the
-- set without hardcoding names, and so a future kit item stays in sync.
local function palette_groups(groups)
	local out = {lw_palette = 1}
	for key, value in pairs(groups or {}) do
		out[key] = value
	end
	return out
end

local function register(name, def)
	def.groups = palette_groups(def.groups)
	if def.is_ground_content == nil then
		def.is_ground_content = false
	end
	core.register_node("lw_nodes:" .. name, def)
end

