--------------------------------------------------------------------------
-- Architecture
--------------------------------------------------------------------------

-- Plain fixed nodeboxes. No connected textures: WebGL is happier and the
-- browser client does not have to ship a second tile set per material.
local function register_stair_and_slab(base, description, tiles, groups)
	register("stair_" .. base, {
		description = description .. " Stair",
		drawtype = "nodebox",
		tiles = tiles,
		paramtype = "light",
		paramtype2 = "facedir",
		on_place = core.rotate_node,
		node_box = {
			type = "fixed",
			fixed = {
				{-0.5, -0.5, -0.5, 0.5, 0.0, 0.5},
				{-0.5, 0.0, 0.0, 0.5, 0.5, 0.5},
			},
		},
		groups = groups,
	})
	register("slab_" .. base, {
		description = description .. " Slab",
		drawtype = "nodebox",
		tiles = tiles,
		paramtype = "light",
		node_box = {type = "fixed", fixed = {-0.5, -0.5, -0.5, 0.5, 0.0, 0.5}},
		groups = groups,
	})
end

register_stair_and_slab("stone_brick", "Stone Brick", {"lw_stone_brick.png"}, {cracky = 2})
register_stair_and_slab("planks", "Wood Plank", {"lw_planks.png"}, {choppy = 2})

