-- A thin panel that hangs on a wall.
--
-- Tile order is +Y, -Y, +X, -X, +Z, -Z, so the art goes on index 6 and the box
-- hugs the -Z side of the node: at facedir 0 the panel faces south, which is
-- the direction a visitor walking north through this world is looking from.
local function register_panel(name, description, front, groups)
	register(name, {
		description = description,
		drawtype = "nodebox",
		tiles = {"lw_frame.png", "lw_frame.png", "lw_frame.png", "lw_frame.png",
			"lw_frame.png", front},
		paramtype = "light",
		paramtype2 = "facedir",
		sunlight_propagates = true,
		on_place = core.rotate_node,
		node_box = {type = "fixed", fixed = {-0.5, -0.5, -0.5, 0.5, 0.5, -0.4375}},
		groups = groups,
	})
end

